class entity
{
public:
	void set_handed_axis(int axis);
	void set_render_scale(const class vector3d& scale);
};

class vector3d
{
public:
	vector3d(float x, float y, float z) : x(x), y(y), z(z) {}
	float x, y, z;
};

class GraphicalMenuSystem
{
public:
	virtual void LoadAll();
};

class FEManager
{
	char pad[8];
public:
	GraphicalMenuSystem* gms;
};

struct SurferData
{
	char pad[544];
	int goofy;
	char tail[104];
};

extern SurferData SurferDataArray[];

enum
{
	SURFER_TRAVIS_PASTRANA = 10,
	SURFER_TONY_HAWK = 12
};

class FEEntityManager
{
public:
	entity* surfer_ent;
	char pad04[4];
	int all_loaded;
	char pad0c[12];
	int current_surfer_index;
	char pad1c[8];
	int loading_surfer_index;
	char pad28[12];
	FEManager* manager;
	char pad38[348];
	entity* board;
	char pad198[148];
	int op_ext;
	char pad230[12];
	int cur_state;
	char pad244[4];
	int next_anim;

	enum
	{
		STATE_SURFER1 = 1,
		SA_IDLE = 0,
		CAM_POS_WALL_2_IN = 1
	};

	void CameraAnim(int anim_pos, float start_time = -2);
	void SurferPlay(int type, float time = -1.0f, int trick_num = 0,
	                int b_trick_num = 0, bool no_blend = false);
	void SetSurferPo(entity* surfer, int surfer_num);
	void ToSurferSelect();
};

void FEEntityManager::ToSurferSelect()
{
	if(!all_loaded) manager->gms->LoadAll();
	if (SurferDataArray[current_surfer_index].goofy && surfer_ent && board)
	{
		surfer_ent->set_handed_axis(-1);
		board->set_handed_axis(-1);
	}

	CameraAnim(CAM_POS_WALL_2_IN);

	SurferPlay(SA_IDLE, -1, 0, 0, true);

	if(surfer_ent) 
		SetSurferPo(surfer_ent, loading_surfer_index);

	// Originally all surfers were flipped so that their reflection would be "reversed"
	// but Jeff requested that TP and TH be flipped again so their animations would 
	// appear different. -Beth
	if(current_surfer_index == SURFER_TRAVIS_PASTRANA || current_surfer_index == SURFER_TONY_HAWK)
		surfer_ent->set_render_scale(vector3d(1, 1, 1));
	else surfer_ent->set_render_scale(vector3d(-1, 1, 1));

	op_ext = false;
	cur_state = STATE_SURFER1;
	next_anim = SA_IDLE;
}
